       ${levelHTML}
       ${raceHTML}
       ${identityHTML}
       ${occupationHTML}
       ${personalityHTML}
       ${favoritesHTML}
       ${appearanceHTML}
       ${adornmentsHTML}
       ${equipmentHTML}
       ${ascensionHTML}

       ${detailsDividerHTML}
       <p><span class="property-name">是否缔结红线:</span> <span class="value-main">${isTied}</span></p>
