      cursor: pointer;
      transition: background-color 0.2s;
    }

    .modal-confirm-btn:hover {
      background-color: #c6b8a5;
    }

    @keyframes fadeIn {
      from {
        opacity: 0;
      }

      to {
        opacity: 1;
      }
    }

    @keyframes slideIn {
      from {
        transform: translateY(-30px);
        opacity: 0;
      }

      to {
        transform: translateY(0);
        opacity: 1;
      }
    }


    @media (max-width: 600px) {
      body {
        padding: 10px;
      }

      .creator-scroll {
        padding: 20px;
      }

      .main-title {
        font-size: 1.5em;
      }

      label {
        font-size: 1em;
      }

      .attributes-container {
        grid-template-columns: 1fr;
      }

      .modal-content {
        width: 95%;
        margin: 10% auto;
      }
    }
  </style>
