    .skill-option input[type='checkbox']:checked::after,
    .skill-option input[type='radio']:checked::after {
      content: '✔';
      color: #fff;
      font-size: 11px;
      position: absolute;
      top: 50%;
      left: 50%;
      transform: translate(-50%, -50%);
